#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Phase B：15 张理论卡。"""
import json, os
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__))); DATA=os.path.join(ROOT,"site","data")
T=[]
def add(**kw): T.append(kw)
add(id="theory-volume-rendering",title="体渲染积分：把 3D 场画成 2D 像素",direction="d3-scene-recon",prereq=[],
 plain="想象一条从相机出发穿过像素的射线。沿射线每隔一段取一个点，问 3D 场「这里有多浓、是什么颜色」，再按「前面的点会挡住后面的点」的规则累加起来，就得到这个像素的颜色。体渲染就是把这条积分写成可微公式，让 2D 像素误差能反传回 3D 场。",
 definition="给定射线 r(t)=o+td，体渲染计算 C(r)=∫T(t)σ(r(t))c(r(t),d)dt，其中 σ 是体积密度、c 是颜色、T(t)=exp(−∫σ) 是透射率；离散化后用 alpha 合成近似。",
 formula=r"$$C(\mathbf{r})=\sum_{i=1}^{N}T_i\left(1-e^{-\sigma_i\delta_i}\right)\mathbf{c}_i,\qquad T_i=\exp\!\left(-\sum_{j<i}\sigma_j\delta_j\right)$$",
 variables=[{"sym":"\\sigma_i","meaning":"第 i 个采样点的密度"},{"sym":"\\delta_i","meaning":"采样间距"},{"sym":"T_i","meaning":"到达第 i 点的透射率"},{"sym":"\\mathbf{c}_i","meaning":"第 i 点的颜色"}],
 derivation="把积分区间切成 N 段，每段密度近似常数；一段的不透明度 α_i=1−exp(−σ_iδ_i)；按从前到后 alpha 合成，得到离散体渲染公式。当 δ→0 时离散和收敛到连续积分。",
 example="一条射线取 64 个点，前 10 个点密度为 0，第 11 个点 σ=50、δ=0.01，则 α≈0.39；若它颜色为红，透射率到该点为 1，像素先得到 0.39 的红；后面的点再按剩余透射率 0.61 叠加。密度越大、间距越大，α 越接近 1，表面越不透明。",
 pseudocode="def render(ray, sigma_fn, color_fn, N=64):\n    ts = linspace(t_n, t_f, N)\n    T = 1.0; C = 0.0\n    for i,t in enumerate(ts):\n        s = sigma_fn(ray(t)); c = color_fn(ray(t))\n        a = 1 - exp(-s * dt)\n        C += T * a * c\n        T *= (1 - a)\n    return C",
 limits=["离散采样会漏掉薄结构","密度场无明确表面，提取网格噪声大","每像素采样多，渲染慢"],
 system_note="NeRF 用 64 粗 + 128 细采样；3DGS 用显式高斯替代采样，渲染快两个量级。",papers=["paper-nerf-2020"])
add(id="theory-hash-encoding",title="多分辨率哈希编码：用查表换速度",direction="d3-scene-recon",prereq=["theory-volume-rendering"],
 plain="NeRF 用一个又大又深的 MLP 记住所有细节，训练很慢。哈希编码把「记细节」的活交给一张可学习的表：坐标按不同分辨率切格子，每个格子查一个短向量，多个分辨率的向量拼起来再送小 MLP。粗格子管大局，细格子管细节，冲突靠多层级平均消化。",
 definition="对输入 x，在 L 个分辨率层级上量化到格子坐标，再用空间哈希映射到大小 T 的表项，取 F 维特征；拼接所有层级的特征送 MLP。",
 formula=r"$$h(\mathbf{x})=\bigoplus_{l=1}^{L}\mathbf{T}_l\!\left[\mathrm{hash}\!\left(\left\lfloor \mathbf{x}\cdot 2^{l}\right\rfloor\right)\bmod T\right]$$",
 variables=[{"sym":"L","meaning":"层级数"},{"sym":"T","meaning":"每层表大小"},{"sym":"\\mathbf{T}_l","meaning":"第 l 层的特征表"}],
 derivation="坐标频率越高，需要的表格越细；单一分辨率要么表太大，要么细节不够。多层级把不同频率解耦：粗层用少量表项覆盖全局，细层用哈希压缩空间。哈希冲突让不同格子共享表项，但多层级拼接与梯度平均使冲突退化为轻微噪声。",
 example="L=16、T=2^19、F=2 时，总表项约 16×52 万×2 个浮点数，显存约 67 MB；若用 512^3 体素存同样特征，需要 1.34 亿个格子，显存大两个量级。Lego 场景训练从数小时降到 1–2 分钟。",
 pseudocode="def encode(x):\n    feats=[]\n    for l in range(L):\n        idx = hash(floor(x * 2**l)) % T\n        feats.append(table[l][idx])\n    return concat(feats)",
 limits=["高分辨率层哈希冲突损失细节","表大小/层数是超参","静态表示，难编辑"],papers=["paper-instant-ngp-2022"])
add(id="theory-gaussian-splatting",title="3D 高斯泼溅：显式基元 + 光栅化",direction="d3-scene-recon",prereq=["theory-volume-rendering"],
 plain="与其沿射线采样，不如把场景直接撒满「会发光的椭圆云团」——每个云团有位置、朝向、大小、透明度和颜色。渲染时把它们投影到屏幕、按远近排序、从前往后混合。因为基元是显式的，排序和混合可以并行，渲染就快了。",
 definition="场景由 N 个 3D 高斯组成，每个高斯有均值 μ、协方差 Σ、不透明度 α、球谐颜色 c；投影到 2D 后用 alpha 合成。",
 formula=r"$$\Sigma'=JW\Sigma W^{\top}J^{\top},\qquad C=\sum_{i\in\mathcal{N}}\mathbf{c}_i\alpha_i\prod_{j<i}(1-\alpha_j)$$",
 variables=[{"sym":"\\Sigma","meaning":"3D 协方差"},{"sym":"J","meaning":"投影雅可比"},{"sym":"W","meaning":"视图变换"},{"sym":"\\alpha_i","meaning":"不透明度"}],
 derivation="3D 高斯经仿射变换仍是高斯；把世界坐标变换到相机坐标（W），再投影到屏幕（J），协方差按 Σ'=JWΣW^T J^T 变换。屏幕上的高斯按深度排序后，每个像素做从前到后的 alpha 合成，得到最终颜色。",
 example="一个高斯均值在相机前 2 m，协方差是各向同性 0.1 m；投影到 1080p 后约占 20×20 像素。若 α=0.5，它在像素中心的贡献是 0.5；后面同位置的高斯只能贡献剩余 0.5 的透射率。数百万个这样的高斯叠加，形成完整图像。",
 pseudocode="def raster(gauss, cam):\n    for g in gauss:\n        g.mu2d, g.S2d = project(g.mu, g.S, cam)\n    for pix in screen:\n        acc=0; T=1\n        for g in sorted_by_depth(gauss):\n            a = g.alpha * exp(-0.5*(pix-g.mu2d)@inv(g.S2d)@(pix-g.mu2d))\n            acc += T*a*g.color; T *= (1-a)\n    return acc",
 limits=["显存随高斯数增长","透明/反射建模弱","稀疏视图易过拟合"],system_note="3DGS 论文 1080p 100+ FPS；显存可达数 GB。",papers=["paper-3dgs-2023"])
add(id="theory-sdf-eikonal",title="SDF 与 Eikonal 正则：让表面干净",direction="d3-scene-recon",prereq=["theory-volume-rendering"],
 plain="NeRF 的密度场像一团雾，没有明确表面。SDF 是「到最近表面的有符号距离」：表面上是 0，外面是正，里面是负。把 SDF 经过一个 S 形函数变成密度，再体渲染，零等值面就成了干净表面。Eikonal 正则要求距离场的梯度长度等于 1，防止它退化成任意函数。",
 definition="SDF f(x) 满足 |∇f|=1（几乎处处）；用 σ=αΨ_β(−f) 把 SDF 转成密度，Ψ_β 是 sigmoid/erf；训练损失含 RGB 重建与 Eikonal 正则。",
 formula=r"$$\sigma(\mathbf{x})=\alpha\,\Psi_\beta(-f(\mathbf{x})),\qquad \mathcal{L}_{\mathrm{eik}}=\left(\|\nabla f(\mathbf{x})\|-1\right)^2$$",
 variables=[{"sym":"f","meaning":"SDF"},{"sym":"\\beta","meaning":"表面锐度温度"},{"sym":"\\Psi_\\beta","meaning":"S 形变换"}],
 derivation="体渲染的不透明度 α_i 由相邻采样点的 SDF 变换值之差决定；当采样跨过零等值面时，Ψ(−f) 从接近 0 跳到接近 1，α 出现峰值。β 越小，跳变越陡，表面越锐。Eikonal 正则来自距离函数的定义：沿梯度方向走单位长度，距离变化 1。",
 example="一个球半径 1，SDF f(x)=|x|−1。在 x=(0,0,0) 处 f=−1，σ=αΨ(1)≈α；在 x=(0,0,2) 处 f=1，σ≈0；在表面 |x|=1 处 f=0，σ=α/2。沿射线从外到内，密度在表面附近集中，体渲染得到清晰边界。",
 pseudocode="def sdf_loss(sdf, rays, gt):\n    rgb = volume_render(sdf, rays)\n    eik = ((grad(sdf, pts).norm(dim=-1) - 1)**2).mean()\n    return mse(rgb, gt) + lam * eik",
 limits=["β 退火敏感","薄结构/非闭合表面难","训练慢"],papers=["paper-neus-2021","paper-volsdf-2021"])
add(id="theory-triplane",title="三平面表示：把 3D 降成 2D 卷积",direction="d3-native-rep",prereq=[],
 plain="直接生成 3D 体素太费显存，直接生成隐式 MLP 又难用 2D 卷积。三平面把 3D 空间拆成三张互相垂直的 2D 特征图（xy、xz、yz）；查询一个 3D 点时，分别在三张图上取对应位置的特征，拼起来送小 MLP。这样生成器可以用成熟的 2D 卷积，显存也降了一个维度。",
 definition="三平面 T_xy,T_xz,T_yz 是三张 2D 特征图；3D 点 x 的特征是三个双线性插值结果的拼接，再经 MLP 解码为密度/颜色/SDF。",
 formula=r"$$F(\mathbf{x})=\mathrm{MLP}\!\left(\mathrm{interp}(T_{xy},\mathbf{x}),\mathrm{interp}(T_{xz},\mathbf{x}),\mathrm{interp}(T_{yz},\mathbf{x})\right)$$",
 variables=[{"sym":"T_{xy},T_{xz},T_{yz}","meaning":"三张正交平面特征图"},{"sym":"\\mathrm{interp}","meaning":"双线性插值"}],
 derivation="任意 3D 点可以投影到三个正交平面，得到三组 2D 坐标；三张平面共同覆盖 3D 空间。平面分辨率 N×N 时，三平面参数量是 3N²，而体素是 N³；在 N=256 时差两个数量级。三平面之间有冗余，但冗余反而帮助 2D 卷积学习共享结构。",
 example="N=256、通道 32：三平面约 3×256×256×32≈630 万参数；同分辨率体素是 256³×32≈5.4 亿，差 85 倍。EG3D 用三平面生成 512×512 人脸，单卡可训。",
 pseudocode="def query(planes, x):\n    xy = grid_sample(planes[0], x[..., :2])\n    xz = grid_sample(planes[1], x[..., [0,2]])\n    yz = grid_sample(planes[2], x[..., 1:])\n    return mlp(cat([xy,xz,yz]))",
 limits=["三平面有对称冗余","固定拓扑，难部件编辑","几何真值弱"],papers=["paper-eg3d-2021"])
add(id="theory-diffusion-score",title="扩散得分与噪声预测",direction="d3-sds",prereq=[],
 plain="扩散模型先学会「把图弄脏」：每一步加一点高斯噪声。然后它学会反向：给定一张脏图和时间步，预测「刚才加进去的噪声是什么」。这个预测噪声的方向，近似指向「更干净的图」；把很多步的方向接起来，就能从纯噪声生成图像。",
 definition="前向过程 x_t=√ᾱ_t x_0+√(1−ᾱ_t)ε；网络 ε_θ(x_t,t) 预测噪声；得分 ∇log p_t(x)≈−ε_θ/√(1−ᾱ_t)。",
 formula=r"$$\mathbf{x}_t=\sqrt{\bar\alpha_t}\mathbf{x}_0+\sqrt{1-\bar\alpha_t}\,\epsilon,\qquad \nabla_{\mathbf{x}}\log p_t(\mathbf{x})\approx-\frac{\epsilon_\theta(\mathbf{x}_t,t)}{\sqrt{1-\bar\alpha_t}}$$",
 variables=[{"sym":"\\bar\\alpha_t","meaning":"累计噪声系数"},{"sym":"\\epsilon_\\theta","meaning":"噪声预测网络"}],
 derivation="由高斯转移核 p_t(x_t|x_0)=N(√ᾱ_t x_0,(1−ᾱ_t)I)，对 x_t 求对数梯度得 −(x_t−√ᾱ_t x_0)/(1−ᾱ_t)；用 ε 表示 x_t−√ᾱ_t x_0=√(1−ᾱ_t)ε，即得得分与噪声预测的关系。",
 example="t 很大时 ᾱ_t≈0，x_t 几乎是纯噪声，得分很小；t 很小时 ᾱ_t≈1，噪声预测接近真实残差，得分很大。生成时从纯噪声开始，每一步减去一点预测噪声，逐步回到清晰图。",
 pseudocode="def train_step(x0):\n    t = randint(1,T); eps = randn_like(x0)\n    xt = sqrt(ab[t])*x0 + sqrt(1-ab[t])*eps\n    loss = mse(eps_theta(xt,t), eps)\n    return loss",
 limits=["多步采样慢","得分估计有方差","条件控制需 CFG"],papers=["paper-dreamfusion-2022"])
add(id="theory-sds",title="Score Distillation Sampling：把 2D 先验蒸进 3D",direction="d3-sds",prereq=["theory-diffusion-score"],
 plain="3D 模型渲染出一张图，把这张图加噪后送给 2D 扩散模型，问它「你觉得噪声应该是什么」。扩散模型的答案与真实噪声的差，就是一个「往更像文本描述的方向走」的梯度。用这个梯度更新 3D 参数，不需要任何 3D 训练数据。",
 definition="SDS 梯度 ∇_θ L_SDS=E[w(t)(ε_φ(x_t;y,t)−ε)∂x/∂θ]，其中 x 是 3D 渲染图，ε_φ 是冻结扩散模型的噪声预测。",
 formula=r"$$\nabla_\theta\mathcal{L}_{\mathrm{SDS}}=\mathbb{E}_{t,\epsilon}\!\left[w(t)\big(\epsilon_\phi(\mathbf{x}_t;y,t)-\epsilon\big)\frac{\partial \mathbf{x}}{\partial\theta}\right]$$",
 variables=[{"sym":"\\mathbf{x}","meaning":"3D 渲染图"},{"sym":"\\epsilon_\\phi","meaning":"冻结扩散模型"},{"sym":"y","meaning":"文本条件"},{"sym":"\\partial\\mathbf{x}/\\partial\\theta","meaning":"渲染雅可比"}],
 derivation="把渲染图 x 看作 θ 的函数；扩散模型给出图像空间的得分方向；用链式法则乘渲染雅可比，得到 θ 空间的更新方向。SDS 省略了得分中的一些项，因此不是严格得分，但实践上足以把渲染图推向高概率区域。",
 example="渲染 64×64 的图，加噪到 t=500，扩散模型预测噪声 ε_φ；若 ε_φ 与真实 ε 差 0.3，权重 w=1，雅可比把每个像素的变化映射到 NeRF 参数；一次更新后，渲染图的纹理更接近文本。重复 15k 步，约 1.5 小时。",
 pseudocode="def sds_step(theta, text):\n    x = render(theta)\n    t = randint(0,T); eps = randn_like(x)\n    xt = add_noise(x,t,eps)\n    eps_hat = diffusion(xt,text,t)\n    g = (eps_hat-eps) * jacobian(x,theta)\n    theta -= lr*g",
 limits=["不是严格得分，有偏","每资产数十分钟到数小时","多面/过饱和"],papers=["paper-dreamfusion-2022"])
add(id="theory-vsd",title="Variational Score Distillation：从单点到分布",direction="d3-sds",prereq=["theory-sds"],
 plain="SDS 把 3D 渲染当成一个点，所以生成结果单一、容易过饱和。VSD 把 3D 参数看成一个分布：除了冻结的 2D 扩散模型，再训练一个「粒子」模型来近似当前 3D 分布的得分。两个得分相减，就是在把 3D 分布往文本分布推。",
 definition="VSD 梯度 ∇_θ L_VSD=E[w(t)(ε_φ(x_t;y,t)−ε_ψ(x_t;c,t))∂x/∂θ]，其中 ε_ψ 是用渲染图训练的粒子模型。",
 formula=r"$$\nabla_\theta\mathcal{L}_{\mathrm{VSD}}=\mathbb{E}\!\left[w(t)\big(\epsilon_\phi(\mathbf{x}_t;y,t)-\epsilon_\psi(\mathbf{x}_t;c,t)\big)\frac{\partial \mathbf{x}}{\partial\theta}\right]$$",
 variables=[{"sym":"\\epsilon_\\phi","meaning":"冻结扩散模型"},{"sym":"\\epsilon_\\psi","meaning":"粒子模型"}],
 derivation="最小化 3D 分布 q(θ) 与文本条件分布 p(θ|y) 的 KL，其梯度是 E_q[∇log q−∇log p]。∇log p 由冻结扩散模型给出，∇log q 由粒子模型近似；两者相减即 VSD。粒子模型随 q 更新，形成对抗式的最小化。",
 example="粒子 LoRA rank=64，每步用当前渲染图训练一次去噪；若冻结模型预测噪声 0.8、粒子预测 0.5，差 0.3 就是更新方向。粒子越准，VSD 越接近真实分布梯度，多样性越好。",
 pseudocode="def vsd_step(theta, particle, text):\n    x = render(theta)\n    eps_phi = diffusion(add_noise(x), text)\n    eps_psi = particle(add_noise(x))\n    theta -= lr * (eps_phi - eps_psi) * jacobian(x, theta)\n    particle.update(x)",
 limits=["需额外粒子模型","显存/时间开销大","超参多"],papers=["paper-prolificdreamer-2023"])
add(id="theory-multiview-consistency",title="多视图一致性：让背面也讲得通",direction="d3-multiview",prereq=["theory-diffusion-score"],
 plain="单图生 3D 的难点是背面。多视图扩散让模型一次生成几个视角，并让这些视角在生成时互相「看到」：共享注意力、共享 3D 体积、或共享法线。这样同一物体在不同视角下不会各长各的。",
 definition="给定参考图 I 与一组相机位姿 {c_i}，生成 {I_i}，使它们在 3D 上一致：同一表面点的颜色/法线在不同视角下相容。",
 formula=r"$$\mathcal{L}_{\mathrm{cons}}=\sum_{i<j}\left\|\mathrm{Warp}(I_i,c_i,c_j)-\mathrm{Warp}(I_j,c_j,c_i)\right\|^2$$",
 variables=[{"sym":"\\mathrm{Warp}","meaning":"按深度把视角 i 投影到视角 j"},{"sym":"c_i","meaning":"相机位姿"}],
 derivation="若两个视角看到同一表面，按深度做重投影后颜色应一致；差异就是一致性损失。生成模型没有真值深度时，用共享注意力/3D 体积隐式实现类似约束。",
 example="视角 A 看到椅子左扶手，视角 B 看到右扶手；把 A 的像素按深度投到 B，若颜色差 0.2，说明两视角对同一表面预测不一致。MVDream 用跨视角注意力把差异压到 0.05 以下。",
 pseudocode="def consistency(imgs, depths, cams):\n    loss=0\n    for i,j in pairs:\n        warped = warp(imgs[i], depths[i], cams[i], cams[j])\n        loss += mse(warped, imgs[j])\n    return loss",
 limits=["遮挡/无深度时难算","背面仍靠幻想","视角数固定"],papers=["paper-mvdream-2023","paper-syncdreamer-2023"])
add(id="theory-lrm",title="LRM：一次前向出三平面",direction="d3-feedforward",prereq=["theory-triplane"],
 plain="LRM 把「重建」变成「预测」：输入一张图，ViT 把它切成 token，Transformer 用 cross-attention 把这些 token 变成三平面；三平面再体渲染出多视角图，用渲染损失训练。推理时一次前向就出 3D，不用逐场景优化。",
 definition="LRM 学习映射 f_θ: (I,c)→T，T 是三平面；训练损失是渲染图与真值的差异；推理一次前向。",
 formula=r"$$\mathbf{T}=\mathrm{Transformer}_\theta(I,\mathbf{c}),\qquad \mathcal{L}=\sum_{v}\left\|\mathrm{VolumeRender}(\mathbf{T},\mathbf{c}_v)-I_v\right\|^2$$",
 variables=[{"sym":"I","meaning":"输入图"},{"sym":"\\mathbf{T}","meaning":"三平面"},{"sym":"\\mathbf{c}_v","meaning":"监督视角"}],
 derivation="三平面是可微的 3D 表示；只要能用它渲染出图，就能用多视角渲染损失训练编码器。Transformer 的 cross-attention 把图像 token 分配到三平面 token，等价于学习「图像特征 → 3D 特征」的映射。",
 example="输入 512×512 图，DINO ViT 出 1024 个 token；24 层 Transformer 解码成 3×64×64×32 三平面；渲染 16 个视角，与 Objaverse 真值算 MSE+LPIPS；50 万物体训练后，推理约 10 秒。",
 pseudocode="def forward(img, cam):\n    tokens = vit(img)\n    tri = transformer(tokens, cam)\n    return tri\n\ndef loss(tri, views):\n    return sum(mse(volume_render(tri, c), I) for c,I in views)",
 limits=["背面细节靠数据先验","网格提取有分辨率损失","训练成本高"],papers=["paper-lrm-2023"])
add(id="theory-slat",title="结构化 3D 潜变量 SLAT",direction="d3-feedforward",prereq=["theory-lrm"],
 plain="三平面是稠密的，高分辨率时显存吃不消；高斯/网格又各自为政。SLAT 把 3D 资产表示成「稀疏体素 + 每个体素的局部特征」：只在有物体的地方存特征，既省算力，又能用不同解码器解成高斯、网格或辐射场。",
 definition="SLAT 是稀疏体素集合，每个体素带局部特征；3D DiT 在 SLAT 空间做 rectified flow；解码器把 SLAT 解成多种输出。",
 formula=r"$$\mathrm{SLAT}=\{(\mathbf{p}_k,\mathbf{f}_k)\}_{k\in\mathcal{V}_{\mathrm{occ}}},\qquad \mathbf{z}_{t}=\mathbf{z}_0+(1-t)\epsilon$$",
 variables=[{"sym":"\\mathcal{V}_{\\mathrm{occ}}","meaning":"占用体素集合"},{"sym":"\\mathbf{f}_k","meaning":"体素局部特征"},{"sym":"\\mathbf{z}_t","meaning":"扩散潜变量"}],
 derivation="稠密三平面的参数量随分辨率平方增长；稀疏体素只存占用区域，参数量随表面面积增长。局部特征让每个体素能独立解码，多个解码器共享同一潜变量，实现多格式输出。",
 example="一个椅子在 64³ 网格中占用约 5% 体素，SLAT 只存 1.3 万个体素特征，而稠密三平面要存 3×64²×32≈39 万；显存降一个量级。同一个 SLAT 可解成高斯（实时渲染）或网格（进引擎）。",
 pseudocode="def encode(voxels):\n    return [(p, f) for p,f in voxels if occupied(p)]\n\ndef decode(z, kind):\n    return {'gauss': gauss_head(z), 'mesh': mesh_head(z)}[kind]",
 limits=["稀疏体素分辨率限制细节","管线复杂","显存仍高"],papers=["paper-trellis-2024"])
add(id="theory-mesh-tokenization",title="网格 tokenization：把三角面变成语言",direction="d3-mesh-topo",prereq=[],
 plain="网格是点和面的集合，不能直接喂给 Transformer。tokenization 把它变成序列：每个面片编码成 token，按邻接关系排成一条「句子」。相邻面片共享边，所以可以只编码新顶点，序列就短了一半。",
 definition="网格 M 被映射成 token 序列 (t_1,...,t_N)，每个 token 编码一个面片的顶点/邻接；自回归模型学习 p(t_i|t_<i)。",
 formula=r"$$p(\mathcal{M})=\prod_{i=1}^{N}p(t_i\mid t_{<i}),\qquad \mathrm{AMT}(\mathcal{M})\approx\frac{1}{2}\mathrm{VTT}(\mathcal{M})$$",
 variables=[{"sym":"t_i","meaning":"第 i 个面片 token"},{"sym":"\\mathrm{AMT}","meaning":"相邻网格 tokenization"}],
 derivation="若每个面片独立编码三个顶点，相邻面片会重复编码共享边；按 DFS 遍历面片，相邻面片只新增一个顶点，序列长度约减半。Transformer 在 token 序列上做 next-token prediction，解码器把 token 还原成面片。",
 example="一个 800 面的网格，逐面三顶点需要 2400 个顶点 token；AMT 只需约 1200 个，序列减半。同样 4096 的上下文，AMT 能生成约 1600 面，而逐面编码只能生成约 800 面。",
 pseudocode="def tokenize(mesh):\n    seq=[]\n    for face in dfs(mesh):\n        seq.append(new_vertex(face))\n    return seq",
 limits=["长序列限制复杂度","拓扑合法性需检查","量化损失细节"],papers=["paper-meshgpt-2023","paper-meshanything-v2-2024"])
add(id="theory-pbr",title="PBR 材质：让生成资产能重光照",direction="d3-data-production",prereq=[],
 plain="只给颜色，资产进引擎后换灯光就假。PBR 把表面拆成反照率、粗糙度、金属度等通道，用物理公式算光照。生成模型要输出这些通道，还要把照片里的光照「去烘培」（delighting），否则阴影会被当成颜色。",
 definition="PBR 渲染用 BRDF 计算像素：漫反射项与镜面项由反照率、粗糙度、金属度、法线决定；生成任务要预测这些通道并去除输入图的光照。",
 formula=r"$$L_o=\int_{\Omega}f_r(\omega_i,\omega_o)L_i(\omega_i)(\mathbf{n}\cdot\omega_i)\,d\omega_i,\qquad f_r=\frac{\mathbf{a}}{\pi}+\frac{DFG}{4(\mathbf{n}\cdot\omega_i)(\mathbf{n}\cdot\omega_o)}$$",
 variables=[{"sym":"\\mathbf{a}","meaning":"反照率"},{"sym":"r","meaning":"粗糙度"},{"sym":"m","meaning":"金属度"},{"sym":"\\mathbf{n}","meaning":"法线"}],
 derivation="渲染方程对入射光积分；BRDF 分为漫反射（Lambert）与镜面（Cook-Torrance）；镜面项含法线分布 D、几何遮蔽 G、菲涅尔 F。金属度决定是否用反照率作为镜面颜色。",
 example="一个金属杯：反照率接近 1、金属度 1、粗糙度 0.2，换暖光后高光偏暖；若把照片阴影烘进反照率，换冷光后杯子仍带暖色阴影，显得脏。delighting 把低频光照从反照率中分离。",
 pseudocode="def pbr_shade(a, r, m, n, l, v):\n    f0 = mix(0.04, a, m)\n    D = ggx(n, l, v, r)\n    G = smith(n, l, v, r)\n    F = fresnel(f0, l, v)\n    return (1-F)*a/pi + F*D*G/(4*ndotl*ndotv)",
 limits=["材质真实感受数据限制","光照解耦不彻底","UV 展开可能失败"],papers=["paper-sf3d-2024","paper-hunyuan3d-21-2025"])
add(id="theory-scene-consistency",title="场景一致性：长距离不漂移",direction="d3-scene-world",prereq=["theory-multiview-consistency"],
 plain="生成一个房间容易，生成一条街难：相机走远后，新生成的画面会和之前的墙、地板对不上。场景一致性要求新视角与已有几何在重叠区域对齐，并把新内容融合进同一张地图，而不是每帧各画各的。",
 definition="给定已建场景 M_t 与新视角 c_{t+1}，生成 I_{t+1} 并融合，使重叠区域的重投影误差最小，且新几何与旧几何连续。",
 formula=r"$$\mathcal{M}_{t+1}=\mathcal{M}_t\cup\mathrm{BackProject}(I_{t+1},D_{t+1},\mathbf{c}_{t+1}),\qquad \min\sum_{p\in\Omega}\|\pi(M_t,p)-I_{t+1}(p)\|^2$$",
 variables=[{"sym":"\\Omega","meaning":"重叠区域"},{"sym":"\\pi","meaning":"重投影"}],
 derivation="相机移动后，旧场景在新视角下应产生可预测的渲染；把渲染图与新生成图在重叠区对齐，差异就是漂移。融合时只新增未见区域，重叠区用旧几何约束，才能抑制长距离漂移。",
 example="相机从客厅走到走廊，旧墙在新视角下应占画面左侧 30%；若生成图里墙跑到了右侧，重投影误差大，说明漂移。Text2Room 用连续对齐把误差压到几个像素。",
 pseudocode="def expand(scene, pose):\n    render = scene.render(pose)\n    new = diffusion(render, pose)\n    mask = overlap(render, new)\n    scene.fuse(new, mask)\n    return scene",
 limits=["重叠区检测难","长距离仍漂移","显存随场景增长"],papers=["paper-text2room-2023","paper-wonderworld-2024"])
add(id="theory-3d-data-scaling",title="3D 数据 scaling：规模决定上限",direction="d3-data-production",prereq=[],
 plain="2D 模型靠上亿图文对起飞，3D 模型长期只有几十万资产。Objaverse 把规模推到 80 万，Objaverse-XL 推到 1000 万；实验表明，新视角合成质量随数据规模提升。数据是 3D 生成的天花板。",
 definition="3D 数据 scaling 指用更大规模、更多样的 3D 资产与渲染图训练模型，观察下游生成/重建指标随规模的变化。",
 formula=r"$$\mathcal{D}_{\mathrm{XL}}=\bigcup_{s\in\mathcal{S}}\mathcal{D}_s,\qquad \mathrm{Quality}=f(|\mathcal{D}|,\mathrm{diversity},\mathrm{quality})$$",
 variables=[{"sym":"\\mathcal{D}_s","meaning":"第 s 个数据源"},{"sym":"|\\mathcal{D}|","meaning":"数据规模"}],
 derivation="3D 生成是数据驱动的映射学习；数据覆盖的类别、视角、材质越广，模型对未见物体的先验越完整。规模增加带来收益，但受质量、重复、许可与算力限制，存在递减。",
 example="Zero-1-to-3 在 Objaverse 80 万上训练，新视角 PSNR 约 18；扩到 Objaverse-XL 1000 万、1 亿渲染图后，PSNR 提升 2–3 dB；继续扩到 1 亿资产，收益变小但方向仍正。",
 pseudocode="for n in [1e5, 1e6, 1e7]:\n    data = sample(objaverse_xl, n)\n    model = train(zero123, render(data))\n    report(eval(model))",
 limits=["版权/许可复杂","质量参差","算力成本高"],papers=["paper-objaverse-2022","paper-objaverse-xl-2023"])
json.dump(T,open(os.path.join(DATA,"theory.json"),"w",encoding="utf-8"),ensure_ascii=False,indent=2)
